#!/usr/bin/env bash
# v5: RL with a Little's-law reward + larger KL + checkpoint selection on validation, conservative few-shot
# adaptation for every method, and the missing random-event runs of the rule-based baselines.
# Run each stage under screen (this round may use GPUs 0-7):
#   bash scripts/screen_run.sh v5_rules     bash scripts/v5_pipeline.sh rules
#   bash scripts/screen_run.sh v5_fewshot   bash scripts/v5_pipeline.sh fewshot
#   bash scripts/screen_run.sh v5_rl        bash scripts/v5_pipeline.sh rl
# Stages skip work whose output exists, so they can be restarted. Do not edit this file while a stage runs
# (bash reads scripts incrementally).
set -uo pipefail
ulimit -c 0
cd "$(dirname "$0")/.."
P=.venv/bin/python
HELD="France_Massy SouthKorea_Songdo Hongkong_YMT"
BUDGETS=${BUDGETS:-"1 10 50"}
JOBS=${JOBS:-16}  # CPU episodes per stage; RL rollouts are the critical path (10 h budget)
STUDENT=${STUDENT:-unitsa-jev-0.5B-full}
BACKBONE=${BACKBONE:-$HOME/zzy/hf_models/Qwen2.5-0.5B-Instruct}
FMT=${FMT:-full}
RL=rl5-${STUDENT#unitsa-jev-}  # selected checkpoint; the two runs are ${RL}a (KL 0.2) and ${RL}b (KL 0.5)
RL_STEPS=${RL_STEPS:-200000}  # ~3.5 h; v4 peaked on the training junctions at 75-150k
mkdir -p logs/v5
stage() { echo "$(date '+%F %T') == $*"; }

rules() {
  stage "rule-based baselines under the random event sets"
  J="Beijing_Beihuan Beijing_Beishahe Beijing_Changjianglu Beijing_Gaojiaoyuan Beijing_Pinganli Beijing_Yongrunlu Chengdu_Chenghannanlu Chengdu_Guanghua Tianjin_zhijingdao $HELD"
  ENVS=""; for net in easy normal; do for pat in low_density high_density fluctuating_commuter increasing_demand random_perturbation; do ENVS="$ENVS ${net}_$pat"; done; done
  mkdir -p logs/sumo_runs
  for j in $J; do for e in $ENVS; do for s in 0 1 2; do for a in fixtime webster sotl maxpressure; do
    for ev in random:1 random:2; do echo "$j $e $s --agent $a --events $ev"; done
  done; done; done; done | CUDA_VISIBLE_DEVICES= xargs -P "$JOBS" -L 1 bash -c \
    'log=logs/sumo_runs/$(echo "$*" | tr " :/" "___").log; '"$P"' run_sumo.py --junction $0 --env_name $1 --seed $2 "${@:3}" --skip_existing > $log 2>&1 || echo "FAILED $*"'
  stage RULES_DONE
}

fewshot() {
  stage "archive the v4 few-shot models and results (once)"
  mkdir -p results/sumo/runs_v4
  for a in presslight attendlight intellilight unitsa; do
    [ -f results/sumo/runs_v4/.archived_$a ] && continue
    for d in ckpt/$a/fs*_*; do [ -d "$d" ] && mv "$d" "ckpt/$a/v4_$(basename "$d")"; done
    find results/sumo/runs -maxdepth 1 -name "*__$a\[fs*" -exec mv -t results/sumo/runs_v4/ {} +
    touch results/sumo/runs_v4/.archived_$a
  done
  stage "conservative few-shot adaptation"
  for b in $BUDGETS; do
    copies=$(( (b + 1) / 2 )); [ $copies -gt 5 ] && copies=5
    for j in $HELD; do for a in presslight attendlight intellilight unitsa; do
      out=ckpt/$a/fs${b}_$j
      [ -f $out/model.zip ] && continue
      if [ $a = unitsa ]; then
        CUDA_VISIBLE_DEVICES=2 $P scripts/train_unitsa.py --junctions $j --episodes $b --copies $copies \
          --init ckpt/unitsa/universal/model.zip --device cuda --out $out > logs/v5/fs_${a}_${b}_$j.log 2>&1 &
      else
        CUDA_VISIBLE_DEVICES=2 $P scripts/train_rl_baseline.py --algo $a --junctions $j --episodes $b \
          --copies $copies --init ckpt/$a/universal/model.zip --device cuda --out $out \
          > logs/v5/fs_${a}_${b}_$j.log 2>&1 &
      fi
    done; done
    wait
  done
  stage "evaluation of the few-shot models"
  fs=""; for b in $BUDGETS; do fs="$fs fs$b"; done
  for a in presslight attendlight intellilight unitsa; do
    ALGO=$a MODELS="$fs" JUNCTIONS="$HELD" JOBS=$JOBS bash scripts/run_rl_eval.sh
  done
  stage FEWSHOT_DONE
}

rl() {
  stage "PPO, Little's-law reward, two KL coefficients"
  i=0
  for kl in 0.2 0.5; do
    v=$([ $i = 0 ] && echo a || echo b)
    if [ ! -f ckpt/${RL}$v/adapter_model.safetensors ]; then
      CUDA_VISIBLE_DEVICES=$i $P scripts/rl_jev.py --model $BACKBONE --adapters ckpt/$STUDENT --state_format $FMT \
        --junctions train --workers 24 --total_steps $RL_STEPS --reward little --wait_coef 0.1 --kl_coef $kl \
        --critic_warmup 5 --save_every 15 --out ckpt/${RL}$v > logs/v5/rl_${RL}$v.log 2>&1 &
    fi
    i=$((i + 1))
  done
  wait
  stage "checkpoint selection on validation (training junctions x training patterns, seed 100)"
  [ -f ckpt/$RL/selection.json ] || $P scripts/select_rl_checkpoint.py --model $BACKBONE --adapters ckpt/$STUDENT \
    --runs ckpt/${RL}a ckpt/${RL}b --state_format $FMT --gpus 0 1 2 3 4 5 6 7 --slots 3 --out ckpt/$RL \
    > logs/v5/select_$RL.log 2>&1 || { stage "SELECTION FAILED"; return 1; }
  stage "conservative few-shot PPO from the selected checkpoint"
  g=0
  for b in $BUDGETS; do for j in $HELD; do
    out=ckpt/$RL-fs${b}_$j
    [ -f $out/adapter_model.safetensors ] && continue
    CUDA_VISIBLE_DEVICES=$g $P scripts/rl_jev.py --model $BACKBONE --adapters ckpt/$STUDENT ckpt/$RL \
      --state_format $FMT --junctions $j --episodes $b --workers 10 --n_steps 32 --epochs 1 --lr 5e-6 --kl_coef 0.5 \
      --reward little --wait_coef 0.1 --critic_warmup 0 --critic_state ckpt/$RL/critic.pt \
      --normalizer ckpt/$RL/normalizer.json --save_every 0 --out $out > logs/v5/rl_fs_${b}_$j.log 2>&1 &
    g=$(( (g + 1) % 8 ))
  done; done
  wait
  stage "evaluation, 3 seeds"
  T="--teacher ckpt/unitsa/universal/model.zip --action_type next_or_not --state_format $FMT"
  G="0 1 2 3 4 5 6 7"
  for s in 0 1 2; do
    MODEL=$BACKBONE ADAPTERS="ckpt/$STUDENT ckpt/$RL" SLOTS=3 GPUS="$G" SEED=$s EXTRA="$T" bash scripts/run_sumo_jev.sh v3
    for b in $BUDGETS; do for j in $HELD; do
      MODEL=$BACKBONE ADAPTERS="ckpt/$STUDENT ckpt/$RL ckpt/$RL-fs${b}_$j" SLOTS=3 GPUS="$G" SEED=$s EXTRA="$T" \
        JUNCTIONS=$j bash scripts/run_sumo_jev.sh v3 &
    done; done
    wait
  done
  stage RL_DONE
}

case ${1:-} in
  rules) rules ;;
  fewshot) fewshot ;;
  rl) rl ;;
  *) echo "usage: $0 rules|fewshot|rl"; exit 1 ;;
esac
